+      const torch::Tensor expected =
+          reference(cpu_src, cpu_lse, cpu_slots, rank, base_e);
+      torch::Tensor storage = torch::full({src.numel() + 2}, 19, src.options());
+      torch::Tensor dst = storage.slice(0, 1, -1).view({h, b, v});
