+  auto slots = torch::zeros({2, 4}, opts);
+  auto lengths = torch::zeros({2}, opts);
+  auto output = torch::empty_like(slots);
+  auto output_lengths = torch::empty_like(lengths);
+  EXPECT_DEATH(
