+    EXPECT_TRUE(equal_reused_scores(gather_scores(pool, ordinals), ref.scores));
+    EXPECT_EQ(stats.columns, std::min(kTopk, pages.visible(start, 0)));
+    EXPECT_TRUE(ref.scores[0][0].eq(/*other=*/64).item<bool>());
