+      gather_keys(empty_cache, empty_pages, /*req=*/0, /*shard=*/1);
+  torch::Tensor pool;
+  const auto empty = select_reference(pre,
+                                      empty_keys,
+                                      empty_pages,
+                                      /*shard=*/1,
+                                      /*start=*/0,
+                                      /*rows=*/1,
+                                      pool);
+  EXPECT_TRUE(empty.global_slots.eq(/*other=*/-1).all().item<bool>());
+  EXPECT_TRUE(empty.scores.isneginf().all().item<bool>());
+}
