+torch::Tensor make_tensor(const std::string& key,
+                          torch::IntArrayRef shape,
+                          torch::ScalarType dtype,
+                          const torch::Device& device) {
+  if (dtype == torch::kInt8) {
+    return (test::seeded_tensor(key, shape, torch::kInt8, torch::kCPU)
+                .remainder(17) -
+            8)
+        .to(device);
